gory":"technology-coding","slug":"electrical-technology"},{"name":"Mechanical Technology","level":"fet","category":"technology-coding","slug":"mechanical-technology"},{"name":"Geography","level":"fet","category":"humanities-social-sciences","slug":"geography"},{"name":"History","level":"fet","category":"humanities-social-sciences","slug":"history"},{"name":"Life Orientation","level":"fet","category":"humanities-social-sciences","slug":"life-orientation"},{"name":"Religion Studies","level":"fet","category":"humanities-social-sciences","slug":"religion-studies"},{"name":"Sport and Exercise Science","level":"fet","category":"humanities-social-sciences","slug":"sport-and-exercise-science"},{"name":"Dance Studies","level":"fet","category":"creative-arts-music","slug":"dance-studies"},{"name":"Design","level":"fet","category":"creative-arts-music","slug":"design"},{"name":"Dramatic Arts","level":"fet","category":"creative-arts-music","slug":"dramatic-arts"},{"name":"Music","level":"fet","category":"creative-arts-music","slug":"music"},{"name":"Visual Arts","level":"fet","category":"creative-arts-music","slug":"visual-arts"},{"name":"Equine Studies","level":"fet","category":"vocational-technical","slug":"equine-studies"},{"name":"Nautical Science","level":"fet","category":"vocational-technical","slug":"nautical-science"}]$topics$::jsonb)
    as topic(name text,level text,category text,slug text)
), added as (
  insert into public.subjects(name,slug,category,sort_order)
  select distinct on (t.slug) t.name,t.slug,c.name,500
  from curriculum_topics t join public.subject_categories c on c.slug=t.category
  order by t.slug,t.name
  on conflict do nothing returning id,slug
), catalog as (
  select id,slug from public.subjects
  union all
  select id,slug from added
)
insert into public.subject_education_levels(subject_id,level_code)
select s.id,t.level from curriculum_topics t join catalog s on s.slug=t.slug
on conflict do nothing;
notify pgrst,'reload schema';
